    public static partial class BoatWorldBuilder
    {
        const string Root="Assets/OceanariumFishing",Dir=Root+"/Travel";static Material wood,paint,cream,brass,red,rope,stone;static int meshIndex;
        static Material Mat(string id,Color color){string path=Dir+"/"+id+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.SetColor("_BaseColor",color);m.SetFloat("_Smoothness",.3f);EditorUtility.SetDirty(m);return m;}
        static T Asset<T>(string name)where T:ScriptableObject{var a=AssetDatabase.LoadAssetAtPath<T>(Dir+"/"+name+".asset");if(!a){a=ScriptableObject.CreateInstance<T>();AssetDatabase.CreateAsset(a,Dir+"/"+name+".asset");}return a;}
        static Transform Node(Transform parent,string name,Vector3 p){var t=new GameObject(name).transform;t.SetParent(parent,false);t.localPosition=p;return t;}
        static GameObject Part(Transform t,string name,Vector3 p,Vector3 size,Material m,bool collider=false,PrimitiveType shape=PrimitiveType.Cube)
        {var go=GameObject.CreatePrimitive(shape);go.name=name;go.transform.SetParent(t,false);go.transform.localPosition=p;go.transform.localScale=size;go.GetComponent<Renderer>().sharedMaterial=m;if(!collider)UnityEngine.Object.DestroyImmediate(go.GetComponent<Collider>());return go;}
        static void Beam(Transform t,string name,Vector3 a,Vector3 b,float r,Material m){var g=Part(t,name,(a+b)/2,new(r,(b-a).magnitude,r),m);g.transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);}
        static Mesh SaveMesh(Mesh mesh,string id){var path=Dir+"/"+id+".asset";mesh.name=id;var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(mesh,old);UnityEngine.Object.DestroyImmediate(mesh);EditorUtility.SetDirty(old);return old;}AssetDatabase.CreateAsset(mesh,path);return mesh;}
        static GameObject MeshPart(Transform parent,string name,List<Vector3> vertices,List<int> triangles,Material m)
        {var mesh=new Mesh();mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);mesh.SetUVs(0,vertices.Select(v=>new Vector2(v.x,v.z)).ToList());mesh.RecalculateNormals();mesh.RecalculateBounds();var go=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));go.transform.SetParent(parent,false);go.GetComponent<MeshFilter>().sharedMesh=SaveMesh(mesh,"TravelMesh_"+meshIndex++);go.GetComponent<Renderer>().sharedMaterial=m;return go;}
        static ParticleSystem Particles(Transform t,string name,Vector3 p,Color color,float rate,float size,float speed)
        {var go=Node(t,name,p).gameObject;var ps=go.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=ps.main;main.playOnAwake=false;main.startLifetime=1.6f;main.startSpeed=speed;main.startSize=size;main.startColor=color;main.maxParticles=60;var emission=ps.emission;emission.rateOverTime=rate;var shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Cone;shape.angle=20;shape.radius=.12f;go.transform.localRotation=Quaternion.Euler(-90,0,0);var renderer=go.GetComponent<ParticleSystemRenderer>();renderer.sharedMaterial=Mat("Particle ivory",new Color(.8f,.87f,.84f));return ps;}
        static GameObject CreateBoat()
        {
            var root=new GameObject("OF_FinnBoat");var t=root.transform;const int count=40;var v=new List<Vector3>();var tri=new List<int>();
            // Lofted elliptical hull: narrower keel, flared gunwale, raised pointed bow.
            for(int ring=0;ring<4;ring++)for(int n=0;n<count;n++){float a=n*Mathf.PI*2/count;float z=Mathf.Cos(a)*3.25f;float x=Mathf.Sin(a)*1.45f*(1-.23f*Mathf.Max(0,Mathf.Cos(a)));float f=.48f+ring*.173f;v.Add(new Vector3(x*f,-.4f+ring*.33f+Mathf.Max(0,Mathf.Cos(a))*.28f,z*f));}
            for(int ring=0;ring<3;ring++)for(int n=0;n<count;n++){int a=ring*count+n,b=ring*count+(n+1)%count;tri.AddRange(new[]{a,b,a+count,b,b+count,a+count});}MeshPart(t,"Rounded painted timber hull",v,tri,paint);
            var deckV=new List<Vector3>{new(0,.49f,0)};for(int n=0;n<count;n++){float a=n*Mathf.PI*2/count;deckV.Add(new Vector3(Mathf.Sin(a)*1.27f,.49f,Mathf.Cos(a)*2.95f));}var deckTri=new List<int>();for(int n=0;n<count;n++)deckTri.AddRange(new[]{0,1+(n+1)%count,1+n});MeshPart(t,"Oval wooden deck",deckV,deckTri,wood);
            for(int j=-5;j<=5;j++){float z=j*.48f;float width=Mathf.Sqrt(Mathf.Max(0,1-z*z/9))*2.5f;Part(t,"Individual deck plank",new(0,.52f,z),new(width,.045f,.43f),j%2==0?wood:cream);}
            for(int n=0;n<count;n++){float a=n*Mathf.PI*2/count,b=(n+1)*Mathf.PI*2/count;Beam(t,"Rounded gunwale",new(Mathf.Sin(a)*1.45f*(1-.23f*Mathf.Max(0,Mathf.Cos(a))),.65f+Mathf.Max(0,Mathf.Cos(a))*.28f,Mathf.Cos(a)*3.25f),new(Mathf.Sin(b)*1.45f*(1-.23f*Mathf.Max(0,Mathf.Cos(b))),.65f+Mathf.Max(0,Mathf.Cos(b))*.28f,Mathf.Cos(b)*3.25f),.1f,wood);}
            for(int row=0;row<2;row++)for(int side=-1;side<=1;side+=2){var p=new Vector3(side*.65f,.7f,-.8f+row*1.4f);Part(t,"Passenger seat cushion",p,new(.75f,.16f,.65f),cream);Part(t,"Passenger seat back",p+new Vector3(0,.3f,-.26f),new(.75f,.5f,.1f),wood);Node(t,"Passenger seat "+(row*2+(side+1)/2),p+Vector3.up*.1f);}
            Part(t,"Steering console",new(0,.95f,1.7f),new(.7f,.85f,.5f),wood);var wheel=Part(t,"Captain wheel",new(0,1.45f,1.4f),new(.45f,.06f,.45f),brass,false,PrimitiveType.Cylinder);wheel.transform.localRotation=Quaternion.Euler(65,0,0);Part(t,"Storage compartment",new(0,.7f,2.35f),new(1.2f,.3f,.65f),cream);Part(t,"Storage handle",new(0,.88f,2.35f),new(.22f,.04f,.08f),brass);
            var engine=Node(t,"Engine compartment",new(0,.55f,-2.65f));Part(engine,"Motor casing",new(0,.2f,0),new(.65f,.65f,.6f),red);for(int j=0;j<5;j++)Part(engine,"Engine cooling fin",new(0,.1f+j*.1f,-.32f),new(.5f,.03f,.04f),brass);Part(engine,"Propeller shaft",new(0,-.45f,-.15f),new(.12f,.7f,.12f),brass);
            var damage=Node(t,"Damaged state",Vector3.zero);for(int j=0;j<3;j++){var board=Part(damage,"Split timber patch",new(1.25f,.35f,-1.3f+j*.3f),new(.12f,.35f,.25f),wood);board.transform.localRotation=Quaternion.Euler(j*12,0,25);}Part(damage,"Loose engine cover",new(.5f,.55f,-2.7f),new(.6f,.06f,.65f),red);Beam(damage,"Loose drive linkage",new(-.5f,.7f,-2.8f),new(-.2f,.3f,-3),.06f,brass);
            var repaired=Node(t,"Repaired state",Vector3.zero);Part(repaired,"Repaired hull stripe",new(1.33f,.43f,-.6f),new(.05f,.13f,2.6f),cream);Part(repaired,"Polished engine cover",new(0,1.12f,-2.65f),new(.7f,.08f,.65f),paint);
            for(int s=-1;s<=1;s+=2){Beam(t,"Lantern post",new(s*1.15f,.5f,1.1f),new(s*1.15f,1.5f,1.1f),.06f,wood);Part(t,"Boat lantern",new(s*1.15f,1.4f,1.1f),new(.22f,.3f,.22f),brass);Part(t,"Warm lantern glass",new(s*1.15f,1.4f,.97f),new(.15f,.2f,.02f),cream);}
            for(int n=0;n<20;n++){float a=n*Mathf.PI/10;Part(t,"Coiled rope",new(.8f+Mathf.Sin(a)*.25f,.57f,-2+Mathf.Cos(a)*.25f),new(.08f,.05f,.08f),rope,false,PrimitiveType.Sphere);}Beam(t,"Anchor shank",new(-1.35f,.55f,-1.9f),new(-1.35f,-.15f,-1.9f),.06f,brass);for(int s=-1;s<=1;s+=2)Beam(t,"Anchor fluke",new(-1.35f,-.15f,-1.9f),new(-1.35f+s*.22f,.05f,-1.9f),.06f,brass);
            Beam(t,"Fishing rod in holder",new(-1,.55f,-1.3f),new(-1.2f,2.3f,-2),.025f,wood);Part(t,"Life ring",new(1.42f,.55f,.2f),new(.1f,.55f,.55f),red,false,PrimitiveType.Cylinder);
            Particles(t,"Engine smoke",new(0,1.15f,-2.7f),new(.34f,.37f,.36f),5,.24f,.5f);Particles(t,"Water wake",new(0,.1f,-3.3f),new(.78f,.96f,.94f),18,.3f,.7f);Particles(t,"Repair sparks",new(0,1.1f,-2.65f),new(1,.8f,.3f),14,.08f,1);
            return root;
        }
        static BoatHarbor Harbor(string island,GameObject boatPrefab,IslandRoute[] routes,BoatUpgrade[] upgrades,Vector3 boatPosition,Vector3 spawn)
        {
            var root=new GameObject("Harbor travel — "+island);var h=root.AddComponent<BoatHarbor>();root.AddComponent<BoatTravelHUD>();h.islandId=island;h.routes=routes;h.upgrades=upgrades;h.boat=((GameObject)PrefabUtility.InstantiatePrefab(boatPrefab)).transform;h.boat.SetParent(root.transform);h.boat.position=boatPosition;h.damage=h.boat.Find("Damaged state").gameObject;h.repairedVisual=h.boat.Find("Repaired state").gameObject;h.seats=Enumerable.Range(0,4).Select(n=>h.boat.Find("Passenger seat "+n)).ToArray();h.smoke=h.boat.Find("Engine smoke").GetComponent<ParticleSystem>();h.wake=h.boat.Find("Water wake").GetComponent<ParticleSystem>();h.sparks=h.boat.Find("Repair sparks").GetComponent<ParticleSystem>();h.dockExit=Node(root.transform,"Harbor disembark",spawn);
            var boarding=Node(root.transform,"Boarding point",spawn+Vector3.right*.8f);var collider=boarding.gameObject.AddComponent<BoxCollider>();collider.size=new(1,1.5f,1);collider.center=Vector3.up*.75f;collider.isTrigger=true;boarding.gameObject.AddComponent<BoatInteraction>().harbor=h;
            var npc=Node(root.transform,"Captain Finn",spawn+Vector3.left*1.5f);var appearance=npc.gameObject.AddComponent<CharacterAppearance>();appearance.loadLocal=false;appearance.surface=AssetDatabase.LoadAssetAtPath<Material>(Root+"/Characters/OF_AvatarSurface.mat");var style=new AppearanceData{skin="caramel",hair="short_crop",hat="bucket_hat",outfitColor="navy",glasses="none"};style.Validate();var col=npc.gameObject.AddComponent<CapsuleCollider>();col.height=1.8f;col.radius=.3f;col.center=Vector3.up*.9f;var interaction=npc.gameObject.AddComponent<BoatInteraction>();interaction.harbor=h;interaction.captain=true;var motion=npc.gameObject.AddComponent<CaptainMotion>();motion.harbor=h;motion.style=style;h.captain=npc;var marker=Part(npc,"Quest pennant",new(0,2.2f,0),new(.15f,.35f,.1f),brass);marker.transform.localRotation=Quaternion.Euler(0,0,10);
            return h;
        }
        [MenuItem("Oceanarium Fishing/Build ASTRA 0.7 Travel World")]
        public static void Build()
        {
            if(EditorApplication.isPlaying)throw new InvalidOperationException("Stop Play Mode");Directory.CreateDirectory(Dir);AssetDatabase.Refresh();meshIndex=0;wood=Mat("Marine cedar",new(.46f,.27f,.14f));paint=Mat("Seafoam enamel",new(.19f,.49f,.45f));cream=Mat("Sailcloth ivory",new(.94f,.86f,.64f));brass=Mat("Weathered brass",new(.64f,.49f,.23f));red=Mat("Coral red",new(.79f,.28f,.2f));rope=Mat("Hemp rope",new(.69f,.58f,.37f));stone=Mat("Harbor stone",new(.45f,.5f,.47f));
            string[] ids={"home","town","coral","mangroves","frost"};var routes=new IslandRoute[5];for(int n=0;n<5;n++){var r=Asset<IslandRoute>("Island_"+ids[n]);r.id=ids[n];r.nameKey="travel.island_"+ids[n];r.destination=new[]{Destination.HomeIsland,Destination.TownIsland,Destination.ExplorationIsland01,Destination.ExplorationIsland02,Destination.ExplorationIsland03}[n];r.requiresRepair=n>0;r.requiredTier=n<2?0:n;r.futureLocked=n>1;r.hidden=n>2;r.requiredFlags=n>1?new[]{"future_"+ids[n]}:Array.Empty<string>();r.requirementKey=n>1?"require_"+ids[n]:"repair_required";r.spawn=n==0?new Vector3(1,.9f,-18):new Vector3(0,.9f,-32);r.mapPosition=new[]{new Vector2(.25f,.68f),new Vector2(.65f,.65f),new Vector2(.8f,.25f),new Vector2(.4f,.25f),new Vector2(.15f,.2f)}[n];r.icon=MapIcon(ids[n],n);EditorUtility.SetDirty(r);routes[n]=r;}
            var upgrades=new BoatUpgrade[4];for(int n=0;n<4;n++){var u=Asset<BoatUpgrade>("BoatTier_"+n);u.id="tier_"+n;u.nameKey="travel.tier_"+n;u.tier=n+1;u.price=n*80;u.futureLocked=n>0;u.requiredFlag=n>0?"future_upgrade_"+n:"boat_repaired";EditorUtility.SetDirty(u);upgrades[n]=u;}
            var model=CreateBoat();var prefab=PrefabUtility.SaveAsPrefabAsset(model,Dir+"/FinnBoat.prefab");UnityEngine.Object.DestroyImmediate(model);
            var home=EditorSceneManager.OpenScene(Root+"/Scenes/OF_HomeIsland.unity");var old=GameObject.Find("Harbor travel — home");if(old)UnityEngine.Object.DestroyImmediate(old);var h=Harbor("home",prefab,routes,upgrades,new Vector3(5.8f,.25f,-23),new Vector3(1,.9f,-18));
            var existingResources=GameObject.Find("Finite repair resources");if(existingResources)UnityEngine.Object.DestroyImmediate(existingResources);var res=new GameObject("Finite repair resources").transform;var settings=AssetDatabase.FindAssets("t:IslandArtSettings").Select(g=>AssetDatabase.LoadAssetAtPath<IslandArtSettings>(AssetDatabase.GUIDToAssetPath(g))).First();IslandGeometry.HillHeight=settings.hillHeight;IslandGeometry.Seed=settings.seed;
            Vector2[] positions={new(-4,-14),new(-8,-12),new(-12,-8),new(11,-10),new(14,-6),new(-3,-9),new(-7,-7),new(9,-8),new(-2,-12),new(7,-12)};
            for(int n=0;n<10;n++){var p=positions[n];string resource=n<5?"driftwood":n<8?"scrap":"rope";var t=Node(res,"Pickup "+resource+" "+n,new Vector3(p.x,IslandGeometry.Height(p.x,p.y)+.08f,p.y));var pickup=t.gameObject.AddComponent<BoatResource>();pickup.id="home_repair_"+n;pickup.resource=resource;var c=t.gameObject.AddComponent<BoxCollider>();c.center=new Vector3(0,.2f,0);c.size=new(.9f,.5f,.8f);c.isTrigger=true;ResourceModel(t,resource);}
            var homeEntry=UnityEngine.Object.FindFirstObjectByType<SceneEntry>();var player=homeEntry.player;var terrain=GameObject.Find("Organic island");var ocean=GameObject.Find("Lagoon");var lighting=GameObject.Find("Afternoon sun");EditorSceneManager.SaveScene(home);
            Town(homeEntry,player,terrain,ocean,lighting,prefab,routes,upgrades);EditorSceneManager.OpenScene(Root+"/Scenes/OF_HomeIsland.unity");Localize();AssetDatabase.SaveAssets();Debug.Log("ASTRA 0.7 harbor and Town Island built");
        }
        static void ResourceModel(Transform t,string kind)
        {if(kind=="driftwood"){Beam(t,"Weathered driftwood",new(-.4f,.1f,0),new(.4f,.15f,.1f),.16f,wood);Beam(t,"Broken twig",new(0,.12f,0),new(.2f,.3f,-.2f),.07f,wood);}else if(kind=="scrap"){for(int j=0;j<3;j++){var g=Part(t,"Salvaged metal plate",new(j*.15f-.15f,.08f+j*.05f,0),new(.35f,.045f,.35f),j==1?red:brass);g.transform.localRotation=Quaternion.Euler(0,j*25,j*8);}}else for(int j=0;j<24;j++){float a=j*Mathf.PI/12;Part(t,"Rope bundle loop",new(Mathf.Sin(a)*.28f,.08f,Mathf.Cos(a)*.2f),new(.1f,.08f,.1f),rope,false,PrimitiveType.Sphere);}}
        static Texture2D MapIcon(string id,int type)
        {var tex=new Texture2D(192,144,TextureFormat.RGBA32,false);for(int y=0;y<144;y++)for(int x=0;x<192;x++){float dx=(x-96)/79f,dz=(y-72)/52f;float a=Mathf.Atan2(dz,dx);float r=Mathf.Sqrt(dx*dx+dz*dz);float edge=.84f+.09f*Mathf.Sin(a*3+type)+.05f*Mathf.Cos(a*7);Color c=Color.clear;if(r<edge+.1f)c=new(.35f,.67f,.67f,.7f);if(r<edge)c=new(.91f,.79f,.5f);if(r<edge-.12f)c=type==4?new(.84f,.92f,.9f):type==3?new(.24f,.48f,.37f):new(.4f,.62f,.3f);if(r<edge-.27f&&Mathf.Sin(x*.12f)*Mathf.Cos(y*.1f)>.35f)c=type==4?Color.white:new(.3f,.52f,.29f);tex.SetPixel(x,y,c);}tex.Apply();var path=Dir+"/Map_"+id+".png";File.WriteAllBytes(path,tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);AssetDatabase.ImportAsset(path);return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
    }
